<script setup lang="ts">
import { reactive, ref, computed } from 'vue';
import { request } from '../crm-api';
import type { ApiProduct } from '../api';
const props=defineProps<{customers:{id:number;company:string;contacts:{name:string;channel:string}[]}[];products:ApiProduct[];locale:string}>();
const emit=defineEmits<{saved:[id:number];cancel:[]}>();
const tx=(z:string,e:string)=>props.locale==='zh'?z:e;
const busy=ref(false),error=ref('');
const newLine=()=>({product_id:'',width:'',height:'',unit:'mm',material:'',color:'',control:'',quantity:1,unit_price:''});
const form=reactive({customer_id:'',company:'',contact_name:'',channel:'',source:'phone',reference:'',currency:'NZD',discount:0,shipping:0,tax:0,terms:'',confirmation_note:'',submission_key:crypto.randomUUID(),lines:[newLine()]});
const selectedCustomer=computed(()=>props.customers.find(c=>c.id===Number(form.customer_id)));
const total=computed(()=>form.lines.reduce((sum,l)=>sum+Number(l.quantity)*Number(l.unit_price),0)-Number(form.discount)+Number(form.shipping)+Number(form.tax));
function chooseProduct(index:number){const line=form.lines[index],p=props.products.find(p=>p.id===Number(line.product_id));if(!p)return;line.material=(props.locale==='zh'?p.material_zh:p.material_en)||'';line.unit=p.unit||'mm';line.color=p.colors?.length===1?p.colors[0]:'';line.control=p.controls?.length===1?p.controls[0]:'';}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const result=await request<{id:number}>('orders/manual',{...form,customer_id:form.customer_id?Number(form.customer_id):null,locale:props.locale==='zh'?'zh':'en'});emit('saved',result.id)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
</script>
<template>
  <form class="manual-order" @submit.prevent="save">
    <header class="editor-heading"><span class="eyebrow">{{tx('外部渠道订单','EXTERNAL CHANNEL ORDER')}}</span><h2>{{tx('手工录入订单','Record an order')}}</h2><p>{{tx('记录已经确认的电话、邮件或其他渠道订单。保存后进入订单跟进。','Record a confirmed order from a phone call, email or another channel, then track its delivery.')}}</p></header>
    <section class="form-section"><h3><span>01</span>{{tx('客户与来源','Customer & source')}}</h3><label>{{tx('客户','Customer')}}<select v-model="form.customer_id"><option value="">{{tx('新增客户','New customer')}}</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.company}}</option></select></label><div v-if="!selectedCustomer" class="field-grid"><label>{{tx('公司 / 客户名称','Company / customer name')}}<input v-model="form.company" required maxlength="200" /></label><label>{{tx('联系人','Contact')}}<input v-model="form.contact_name" required maxlength="100" /></label><label>{{tx('联系方式','Contact method')}}<input v-model="form.channel" required maxlength="300" /></label></div><p v-else class="customer-preview">{{selectedCustomer.contacts[0]?.name}} · {{selectedCustomer.contacts[0]?.channel}}</p><div class="field-grid two"><label>{{tx('订单来源','Order source')}}<select v-model="form.source"><option value="phone">{{tx('电话','Phone')}}</option><option value="email">{{tx('邮件','Email')}}</option><option value="wechat">{{tx('微信','WeChat')}}</option><option value="other">{{tx('其他','Other')}}</option></select></label><label>{{tx('外部订单号（可选）','External reference (optional)')}}<input v-model="form.reference" maxlength="200" /></label></div></section>
    <section class="form-section"><h3><span>02</span>{{tx('产品明细','Product details')}}</h3><fieldset v-for="(line,index) in form.lines" :key="index"><legend>{{tx('产品','Item')}} {{index+1}}</legend><div class="field-grid"><label>{{tx('产品','Product')}}<select v-model="line.product_id" required @change="chooseProduct(index)"><option value="">{{tx('请选择','Select a product')}}</option><option v-for="p in products" :key="p.id" :value="p.id">{{locale==='zh'?p.name_zh:p.name_en}}</option></select></label><label>{{tx('宽度','Width')}}<input v-model="line.width" type="number" min="0.01" step="any" required /></label><label>{{tx('高度','Drop')}}<input v-model="line.height" type="number" min="0.01" step="any" required /></label><label>{{tx('单位','Unit')}}<select v-model="line.unit"><option>mm</option><option>inch</option></select></label><label>{{tx('材质','Material')}}<input v-model="line.material" required maxlength="100" /></label><label>{{tx('颜色','Colour')}}<input v-model="line.color" required maxlength="100" /></label><label>{{tx('控制方式','Control')}}<input v-model="line.control" required maxlength="100" /></label><label>{{tx('数量','Quantity')}}<input v-model.number="line.quantity" type="number" min="1" step="1" required /></label><label>{{tx('人工单价','Manual unit price')}}<input v-model="line.unit_price" type="number" min="0" step="0.01" required /></label></div><button v-if="form.lines.length>1" class="text-button" type="button" @click="form.lines.splice(index,1)">{{tx('移除此项','Remove item')}}</button></fieldset><button type="button" class="secondary" @click="form.lines.push(newLine())">+ {{tx('添加产品','Add product')}}</button></section>
    <section class="form-section"><h3><span>03</span>{{tx('金额与确认','Amount & confirmation')}}</h3><div class="field-grid"><label>{{tx('币种','Currency')}}<input v-model="form.currency" required pattern="[A-Z]{3}" maxlength="3" /></label><label>{{tx('折扣','Discount')}}<input v-model.number="form.discount" type="number" min="0" step="0.01" required /></label><label>{{tx('运费','Shipping')}}<input v-model.number="form.shipping" type="number" min="0" step="0.01" required /></label><label>{{tx('税额','Tax amount')}}<input v-model.number="form.tax" type="number" min="0" step="0.01" required /></label></div><label>{{tx('客户确认依据','Customer confirmation')}}<textarea v-model="form.confirmation_note" required maxlength="2000" :placeholder="tx('例如：电话确认的日期、联系人及约定。','For example: date of the call, contact and the agreement.')" /></label><label>{{tx('条款与备注（可选）','Terms & notes (optional)')}}<textarea v-model="form.terms" maxlength="4000" /></label><div class="order-total"><span>{{tx('订单总额','Order total')}}</span><strong>{{form.currency}} {{total.toFixed(2)}}</strong></div></section>
    <p v-if="error" role="alert" class="form-error">{{error}}</p><footer class="editor-actions"><button type="button" class="secondary" :disabled="busy" @click="emit('cancel')">{{tx('取消','Cancel')}}</button><button :disabled="busy">{{busy?tx('保存中…','Saving…'):tx('保存并创建订单','Save and create order')}}</button></footer>
  </form>
</template>
<style scoped>
.manual-order{max-width:960px}.editor-heading{margin-bottom:28px}.eyebrow{font-size:10px;letter-spacing:.12em;color:#68776d}.editor-heading h2{font-size:22px;margin:8px 0}.editor-heading p{font-size:13px;line-height:1.7;color:#68776d;margin:0;max-width:600px}.form-section{border-top:1px solid #e1e7e3;padding:22px 0}.form-section h3{display:flex;gap:12px;align-items:center;font-size:14px;font-weight:600;margin:0 0 18px}.form-section h3 span{color:#87958b;font-size:11px;font-variant-numeric:tabular-nums}.manual-order label{display:block;font-size:12px;margin:0 0 14px}.field-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.field-grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.manual-order input,.manual-order select,.manual-order textarea{display:block;width:100%;min-height:42px;margin-top:6px;padding:10px 12px;border:1px solid #cfd9d2;border-radius:4px;background:#fff;font:13px var(--font-body);box-sizing:border-box;color:#1b2421}.manual-order textarea{min-height:80px;resize:vertical}.manual-order fieldset{margin:0 0 16px;padding:16px;border:1px solid #e0e7e2;border-radius:5px}.manual-order legend{font-size:12px;padding:0 6px;color:#65736a}.manual-order button{min-height:42px;padding:8px 16px;border:1px solid #0f6e5c;border-radius:4px;background:#0f6e5c;color:#fff;font:500 12px var(--font-body);cursor:pointer}.manual-order button.secondary{background:#fff;color:#1b2421;border-color:#cfd9d2}.manual-order .text-button{min-height:32px;padding:4px 0;border:0;background:transparent;color:#8c2f2f}.customer-preview{font-size:13px;color:#68776d}.order-total{display:flex;justify-content:space-between;align-items:center;padding:18px 0 0;border-top:1px solid #e0e7e2;font-size:13px}.order-total strong{font-size:24px;font-weight:600;font-variant-numeric:tabular-nums}.editor-actions{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid #e0e7e2;padding-top:18px}.form-error{color:#8c2f2f;font-size:13px}.manual-order button:disabled{opacity:.5;cursor:default}@media(max-width:600px){.field-grid,.field-grid.two{grid-template-columns:1fr}.editor-heading h2{font-size:20px}.manual-order fieldset{padding:12px}.order-total strong{font-size:20px}.editor-actions button{flex:1}}
</style>
